dashboard.definition:
{
  "title": "DMX Inventory: Datasets",
  "description": "Local and remote datasets known to Ingest Processor.",
  "visualizations": {
    "viz_list": {
      "type": "splunk.table",
      "title": "Datasets (select a row)",
      "dataSources": {
        "primary": "ds_list"
      },
      "options": {
        "count": 20
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "dsid",
                "key": "row.object_id.value"
              }
            ]
          }
        }
      ]
    },
    "viz_raw": {
      "type": "splunk.table",
      "title": "Latest snapshot of selected dataset",
      "dataSources": {
        "primary": "ds_raw"
      },
      "options": {
        "count": 20
      }
    },
    "viz_hist": {
      "type": "splunk.table",
      "title": "Change history of selected dataset",
      "dataSources": {
        "primary": "ds_hist"
      },
      "options": {
        "count": 20
      }
    }
  },
  "dataSources": {
    "ds_list": {
      "type": "ds.search",
      "name": "ds_list",
      "options": {
        "query": "| inputlookup dmx_datasets_current_lookup | table object_id name dataset_kind status modified_time first_seen last_seen | sort name",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_raw": {
      "type": "ds.search",
      "name": "ds_raw",
      "options": {
        "query": "`dmx_index` sourcetype=dmx:dataset object_id=\"$dsid$\" | head 1 | table _time _raw",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_hist": {
      "type": "ds.search",
      "name": "ds_hist",
      "options": {
        "query": "`dmx_index` sourcetype=dmx:change object_type=dataset object_id=\"$dsid$\" | table _time change_type name changed_fields collection_id",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    }
  },
  "defaults": {
    "tokens": {
      "default": {
        "dsid": {
          "value": "none-selected"
        }
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440
    },
    "structure": [
      {
        "item": "viz_list",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1440,
          "h": 420
        }
      },
      {
        "item": "viz_raw",
        "type": "block",
        "position": {
          "x": 0,
          "y": 420,
          "w": 1440,
          "h": 260
        }
      },
      {
        "item": "viz_hist",
        "type": "block",
        "position": {
          "x": 0,
          "y": 680,
          "w": 1440,
          "h": 300
        }
      }
    ],
    "globalInputs": [
      "input_time"
    ]
  }
}
